// A valid speed notification delivered with an older local receipt time. The
// source timestamp is intentionally also older, but freshness ordering is
// defined by the local monotonic receipt time.
inline constexpr std::array<std::uint8_t, 19> late_old_speed{
    0x01, 0x63, 0x00, 0x00, 0x00, 0x00, 0x57, 0x02, 0x00, 0x00, 0x08, 0x00,
    0x80, 0xBB, 0xC8, 0x01, 0x00, 0x00, 0x00,
};

[[nodiscard]] constexpr std::span<const std::uint8_t>
truncated_active_drive() noexcept {
    return std::span<const std::uint8_t>{active_drive}.first(
        active_drive.size() - 1U);
}

